mapper.select:
select tm.sys_id as sysId, dtc.id AS id, dtc.is_deleted AS isDeleted, dtc.disabled AS disabled, dtc.name AS name, dtc.country_code AS countryCode, dtc.parent_code AS parentCode, dtc.code AS code, dtc.type AS type, dtc.index AS index, dtc.source_platform AS sourcePlatform from third_mapping tm inner join dmp_third_city dtc on dtc.id = tm.third_id and dtc.type = tm.type where tm.is_deleted = false and tm.disabled = false and tm.type in ('province','city','district') and dtc.is_deleted = false and dtc.disabled = false and dtc.sourcePlatform = #{params.sourcePlatform}
and tm.sys_id in
#{id}
